<template>
  <div class="s-page s-overview-page">
    <div class="s-page-heading"><div><p class="s-eyebrow">YOUR RESEARCH WORKSPACE</p><h1>数据智能工作台</h1><p>理解数据里的模式，构建新的样本，用实验验证价值。</p></div><RouterLink class="s-button" to="/datasets"><el-icon><Upload /></el-icon>导入数据</RouterLink></div>
    <section class="s-hero-panel"><div class="s-hero-copy"><span class="s-kicker"><span class="s-dot"></span> TIME SERIES DATA INTELLIGENCE</span><h2>理解数据的结构，<br /><span>创造数据的可能。</span></h2><p>连接结构发现、时序生成与质量评估，<br />让每一次数据实验，都有清晰的下一步。</p><div class="s-actions"><button class="s-button primary" :disabled="busy || !studio.connected" @click="demo">{{ busy ? '正在准备数据…' : '开启交互演示' }} <span>↗</span></button><RouterLink class="s-text-link" to="/research">了解科研底座 →</RouterLink></div><small>能源场景示例 · 真实交互流程 · 可导出实验报告</small></div><div class="s-flow-art" aria-label="结构发现、数据生成和验证的示意图"><div class="s-art-label"><span>SEQUENCE EXPLORER</span><span>概念示意</span></div><svg viewBox="0 0 420 200" role="img"><title>时序模式示意，非实验结果</title><defs><pattern id="studio-grid" width="28" height="25" patternUnits="userSpaceOnUse"><path d="M 28 0 L 0 0 0 25" fill="none" stroke="#dbe6dc" stroke-width=".6" /></pattern></defs><rect width="420" height="200" fill="url(#studio-grid)" /><rect x="242" width="178" height="200" fill="#d8ebde" opacity=".45" /><path v-for="(line, index) in waves" :key="index" :d="line" fill="none" :stroke="['#1c7864','#8fa58c','#d4a157'][index]" :stroke-width="index === 0 ? 2.7 : 1.5" :opacity="index === 0 ? 1 : .8" /><line x1="242" x2="242" y1="8" y2="193" stroke="#6a8676" stroke-dasharray="4 5" /><text x="254" y="21" fill="#809483" font-size="9" font-family="monospace">SYNTHESIS SPACE</text></svg><div class="s-art-steps"><span><i>01</i> Discover</span><b>→</b><span><i>02</i> Generate</span><b>→</b><span><i>03</i> Evaluate</span></div><p>Understand → Identify gaps → Generate → Validate</p></div></section>
    <section class="s-research-strip"><span><strong>由科研驱动</strong><br /><small>两项核心研究 · 一个数据工作台</small></span><RouterLink to="/research"><b>APCL</b><span>结构发现</span><em>KDD 2026 · CCF-A</em><span>↗</span></RouterLink><RouterLink to="/research"><b>SDFlow</b><span>时序生成</span><em>NeurIPS 2026 · CCF-A</em><span>↗</span></RouterLink></section>
    <div class="s-section-heading"><h2>一个完整的数据实验</h2><span>从探索到交付，保留每一步证据</span></div><section class="s-workflow-grid"><RouterLink v-for="step in steps" :key="step.number" :to="step.path" class="s-workflow-card"><span class="s-card-number">{{ step.number }} <el-icon><component :is="step.icon" /></el-icon></span><h3>{{ step.title }} <span>↗</span></h3><p>{{ step.text }}</p><small>{{ step.detail }}</small></RouterLink></section>
    <section class="s-stats-row"><div><span>数据资产</span><strong>{{ studio.datasets.length.toString().padStart(2, '0') }}</strong><small>来源与内容指纹</small></div><div><span>结构实验</span><strong>{{ completed('discover').toString().padStart(2, '0') }}</strong><small>可追溯的模式分析</small></div><div><span>生成实验</span><strong>{{ completed('generate').toString().padStart(2, '0') }}</strong><small>数据与独立评估报告</small></div><div><span>统一服务</span><strong class="s-stat-text">鼠先知引擎</strong><small>贯通数据实验的每一步</small></div></section>
    <div class="s-two-col"><section class="s-panel"><div class="s-section-heading"><h2>最近实验</h2><RouterLink to="/datasets" class="s-text-link">全部记录 →</RouterLink></div><div v-if="!studio.jobs.length" class="s-empty compact"><el-icon><DataAnalysis /></el-icon><h3>第一份数据，从这里开始</h3><p>导入 CSV 或开启交互演示，建立你的第一条实验记录。</p></div><button v-for="job in studio.jobs.slice(0, 4)" :key="job.id" class="s-experiment-row" @click="open(job)"><span class="s-experiment-icon"><el-icon><component :is="job.kind === 'discover' ? Aim : MagicStick" /></el-icon></span><span><strong>{{ job.kind === 'discover' ? '结构发现' : '数据生成与评估' }}</strong><small>{{ studio.datasets.find(d => d.id === job.config.dataset_id)?.name }} · {{ date(job.created) }}</small></span><span :class="['s-status', job.status]">{{ status[job.status] }}</span></button></section><section class="s-panel s-opportunity"><span class="s-eyebrow">FROM RESEARCH TO IMPACT</span><h2>稀缺的不只是数据，<br />还有对数据的把握。</h2><p>面向科研人员与工业时序工程师，从能源与设备传感器场景切入，探索结构感知的数据增强。</p><RouterLink to="/research" class="s-text-link">科研基础与产品路线 →</RouterLink><small>当前为产品 MVP；APCL / SDFlow 模型服务接入列入下一阶段。</small></section></div>
  </div>
</template>
<script setup>
import { ref } from 'vue'
import { useRouter } from 'vue-router'
import { Upload, Aim, MagicStick, CircleCheck, DataAnalysis } from '@element-plus/icons-vue'
import { useStudioStore } from '../../stores/studio'
import { date } from '../../components/studio/chartOptions'
const studio = useStudioStore(), router = useRouter(), busy = ref(false)
const status = { completed: '已完成', failed: '失败', queued: '等待中', running: '运行中' }
const completed = kind => studio.jobs.filter(j => j.kind === kind && j.status === 'completed').length
const steps = [{ number: '01', title: '看见数据中的结构', text: '探索模式、代表曲线与样本分布，发现值得进一步检查的覆盖缺口。', detail: 'DISCOVER / 结构与原型', path: '/discover', icon: Aim }, { number: '02', title: '补足需要的数据', text: '选择目标模式，生成候选窗口，构建适用于后续实验的数据资产。', detail: 'GENERATE / 候选与筛选', path: '/generate', icon: MagicStick }, { number: '03', title: '用证据验证用途', text: '从分布、时序特征到留出集下游效用，导出可审查的数据与报告。', detail: 'EVALUATE / 质量与效用', path: '/evaluate', icon: CircleCheck }]
const waves = Array.from({ length: 3 }, (_, j) => Array.from({ length: 141 }, (_, i) => `${i ? 'L' : 'M'}${i * 3},${100 + Math.sin(i / 8 + j * 0.32) * (28 + j * 7) + Math.sin(i / 3.8) * 10 + j * 9}`).join(' '))
async function demo() { busy.value = true; try { const dataset = await studio.addDemo('energy'); await studio.submit('discover', { dataset_id: dataset.id, window: 48, stride: 48, seed: 42 }); router.push('/discover') } catch { /* global error banner */ } finally { busy.value = false } }
function open(job) { studio.openJob(job); router.push(job.kind === 'discover' ? '/discover' : '/evaluate') }
</script>
